 return '<section class="hero pay-hero"><div class="hero-label"><span>'+(s.balance<0?'Saldo a tu favor':'Pendiente de cobro')+'</span>'+(part()!=='all'?'<span class="pill'+(locked?' locked':'')+'">'+icon(locked?'lock':'check')+(locked?'Cerrada':'Abierta')+'</span>':'')+'</div><div class="amount">'+money(Math.abs(s.balance))+'</div><div class="progress" role="progressbar" aria-label="Parte cobrada" aria-valuenow="'+pct+'" aria-valuemin="0" aria-valuemax="100"><i style="width:'+pct+'%"></i></div><div class="breakdown"><div><small>Generado</small><strong>'+money(s.total)+'</strong></div><div><small>Cobrado · '+pct+'%</small><strong>'+money(s.paid)+'</strong></div></div></section>'
