function profileForm(){const st=state.settings,worked=state.rows.filter(r=>r.status==='Presente').sort((a,b)=>a.date.localeCompare(b.date)),places=new Set(worked.map(r=>r.place).filter(Boolean)).size;modal('<h2>Tu perfil</h2><p class="muted">Aparece en los recibos, PDF, Excel e imágenes que compartís.</p><form id="profileForm">'+field('Nombre y apellido','name','text',st.name||'','maxlength="80" autocomplete="name"')+field('Puesto u oficio','job','text',st.job||'','maxlength="80" placeholder="Ej.: Repartidor, Cajera…"')+field('Empleador o empresa','employer','text',st.employer||'','maxlength="80"')+formEnd('Guardar perfil')+'</form><h3>Tu historial</h3><div class="grid stats"><div class="metric"><small>Jornadas</small><b>'+worked.length+'</b></div><div class="metric"><small>Lugares</small><b>'+places+'</b></div><div class="metric"><small>Desde</small><b>'+(worked[0]?dateLabel(worked[0].date).slice(0,5)+'/'+worked[0].date.slice(2,4):'—')+'</b></div></div>');$('profileForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(mutate(()=>{for(const k of ['name','job','employer'])state.settings[k]=String(f.get(k)||'').trim()},'Perfil guardado.'))closeModal()};}
function aboutForm(){modal('<h2>Acerca de Mi Quincena</h2><p class="muted">Versión 3.4.0. Sin publicidad, sin analíticas, sin cuenta. Tus datos quedan en este teléfono.</p><h3>Rutina recomendada</h3><ol><li>Configurá tu tarifa y su fecha de vigencia.</li><li>Registrá cada día con el botón +: lugar, entrada, salida y si te pagan distinto (doble, ×1,5).</li><li>Cuando te pagan, cargá el cobro en Pagos.</li><li>Cerrá la quincena cuando esté revisada.</li><li>Exportá una copia de seguridad de vez en cuando.</li></ol><p class="muted">Un día sin registrar no es una falta. Cerrar una quincena bloquea cambios en jornadas y tarifas; podés seguir cargando cobros.</p><button type="button" class="wide" data-action="guide">'+icon('book')+' Abrir la guía de uso</button>');}
function action(a){if(a==='new')editRow(today());if(a==='rule')ruleForm();if(a==='rates')ratesView();if(a==='payment')paymentForm();if(a==='adjustment')adjustmentForm();if(a==='batch')batchForm();if(a==='appearance')go('settings');if(a==='profile')profileForm();if(a==='about')aboutForm();if(a==='payAll')paymentForm(null,summary().balance);if(a==='exportXlsx')exportExcel('pay');if(a==='reminders')remindersForm();if(a==='backups')backupsForm();if(a==='cloud')cloudForm();if(a==='help')profileForm();if(a==='share')shareSheet();if(a==='guide'){if($('dialog').open)closeModal();go('guide')}if(a==='carry')carryForm();if(a==='wipe'){const t=prompt('Esto borra jornadas, tarifas, cobros y ajustes (no tus preferencias). Exportá una copia antes.\n\nEscribí BORRAR para confirmar.');if(t&&t.trim().toUpperCase()==='BORRAR')mutate(()=>{state.rows=[];state.rules=[];state.payments=[];state.adjustments=[];state.closed=[];state.templates=[]},'Datos borrados.')}if(a==='backup'){prefsSet('last-backup',String(Date.now()));if(tabName==='settings')setTimeout(render,0)}if(a==='backup')download('Mi-Quincena-'+today()+'-respaldo.json','application/json',utf8b64(JSON.stringify(state,null,2)));if(a==='import'){if(window.Android)Android.importFile();else $('file').click()}if(a==='closePeriod'){const key=month()+':'+part(),closed=state.closed.includes(key);if(confirm(closed?'¿Reabrir esta quincena para corregir registros?':'¿Cerrar esta quincena? No marca el saldo como cobrado. Se bloquean cambios en jornadas, ajustes y tarifas.'))mutate(()=>{state.closed=closed?state.closed.filter(k=>k!==key):state.closed.concat(key)},closed?'Quincena reabierta.':'Quincena cerrada.')}}
