function download(name,mime,data){try{if(window.Android){Android.exportFile(name,mime,data);return}const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast('No se pudo exportar: '+e.message)}}
