function excelDate(v){if(v instanceof Date)return [v.getFullYear(),String(v.getMonth()+1).padStart(2,'0'),String(v.getDate()).padStart(2,'0')].join('-');if(typeof v==='number'){const p=XLSX.SSF.parse_date_code(v);return p?`${p.y}-${String(p.m).padStart(2,'0')}-${String(p.d).padStart(2,'0')}`:''}const s=String(v||'').trim();if(/^\d{2}\/\d{2}\/\d{4}$/.test(s))return s.slice(6)+'-'+s.slice(3,5)+'-'+s.slice(0,2);return s;}
function excelTime(v){if(v==null||v==='')return '';if(v instanceof Date)return String(v.getHours()).padStart(2,'0')+':'+String(v.getMinutes()).padStart(2,'0');if(typeof v==='number'){const m=Math.round((v%1)*1440)%1440;return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0')}const s=String(v).trim();const m=s.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);return m?m[1].padStart(2,'0')+':'+m[2]:s;}
function excelRows(b64,mapping){const wb=XLSX.read(b64,{type:'base64',cellDates:true}),rows=[],errors=[],seen=new Set;for(const name of wb.SheetNames){if(['Liquidación','Tarifas','Cobros','Ajustes'].includes(name))continue;const values=XLSX.utils.sheet_to_json(wb.Sheets[name],{header:1,defval:null});let map=mapping||{date:0,place:2,start:3,end:4,status:5,note:6,breakMinutes:7,overnight:8,paid:-1};for(let i=0;i<values.length;i++){const a=values[i];if(!mapping&&a.some(x=>String(x).trim().toUpperCase()==='FECHA')){const norm=a.map(x=>String(x||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toUpperCase());const find=(names,fallback)=>{const x=norm.findIndex(v=>names.includes(v));return x<0?fallback:x};map={date:find(['FECHA'],0),place:find(['LUGAR / ACTIVIDAD','LUGAR','ACTIVIDAD'],2),start:find(['ENTRADA'],3),end:find(['SALIDA'],4),status:find(['ASISTENCIA'],5),note:find(['OBSERVACIONES'],6),breakMinutes:find(['DESCANSO (MIN)','DESCANSO'],-1),overnight:find(['SALIDA DIA SIGUIENTE'],-1),paid:find(['DIA PAGO'],-1)};continue}
 const date=excelDate(a[map.date]);if(!/^\d{4}-\d{2}-\d{2}$/.test(date)){if(i>1&&a[map.date]&&a.slice(2,6).some(x=>x!=null)&&String(a[map.date]).match(/\d/))errors.push(name+' fila '+(i+1)+': fecha no reconocida');continue;}
 try{const raw=String(a[map.status]||'').trim(),status=Core.statuses.find(s=>s.toLowerCase()===raw.toLowerCase());if(status===undefined)throw Error('Asistencia desconocida: '+raw);const r={date,place:String(a[map.place]||''),start:excelTime(a[map.start]),end:excelTime(a[map.end]),status,note:String(a[map.note]||''),breakMinutes:Number(a[map.breakMinutes]||0),overnight:[true,'true','Sí','SI',1].includes(a[map.overnight]),paid:[true,'true','Sí','SI',1].includes(a[map.paid])};Core.validateRow(r);if(seen.has(date))throw Error('Fecha repetida en el archivo');seen.add(date);rows.push(r)}catch(e){errors.push(name+' fila '+(i+1)+': '+e.message)}}}return {rows,errors};}
function parseExcel(b64){const result=excelRows(b64);if(result.errors.length)throw Error(result.errors.join('\n'));if(!result.rows.length)throw Error('No se encontraron fechas en una planilla compatible');return result.rows;}
function importPreview(b64,mapping){let parsed;try{parsed=excelRows(b64,mapping)}catch(e){toast('Archivo rechazado: '+e.message);return}const duplicates=parsed.rows.filter(r=>state.rows.some(x=>x.date===r.date&&(x.status||x.place||x.note))),dupSet=new Set(duplicates.map(r=>r.date));modal('<h2>Revisar Excel</h2><div class="preview">'+parsed.rows.length+' filas válidas · '+duplicates.length+' fechas con datos existentes · '+parsed.errors.length+' errores</div><p class="muted">Revisá los datos antes de incorporarlos. El Excel importa jornadas; tarifas, cobros y preferencias se restauran desde JSON.</p>'+(parsed.errors.length?'<details open><summary>Filas que no se importarán</summary><p class="error">'+parsed.errors.slice(0,30).map(esc).join('<br>')+'</p></details>':'')+select('Si la fecha ya tiene datos','duplicatePolicy',[['keep','Conservar datos del teléfono'],['replace','Reemplazar solo fechas seleccionadas']], 'keep')+'<div id="duplicateChoices" hidden>'+duplicates.map(r=>'<label class="check"><input type="checkbox" name="replaceDate" value="'+r.date+'">'+dateLabel(r.date)+' · '+esc(r.place)+' · '+esc(r.start)+'–'+esc(r.end)+'</label>').join('')+'</div><details><summary>Vista previa de las primeras 10 filas</summary>'+parsed.rows.slice(0,10).map(r=>'<div class="line"><div>'+dateLabel(r.date)+' · '+esc(r.place)+'<small>'+esc(r.start)+'–'+esc(r.end)+' · '+esc(r.status||'Sin registrar')+'</small></div></div>').join('')+'</details><div class="actions"><button class="primary" id="importConfirm" '+(!parsed.rows.length?'disabled':'')+'>Importar filas válidas</button><button id="mapColumns">Asignar columnas</button><button data-close>Cancelar</button></div>');document.querySelector('[name=duplicatePolicy]').onchange=e=>$('duplicateChoices').hidden=e.target.value!=='replace';$('mapColumns').onclick=()=>mappingForm(b64);$('importConfirm').onclick=()=>{try{const replacements=new Set([...document.querySelectorAll('[name=replaceDate]:checked')].map(x=>x.value)),replace=document.querySelector('[name=duplicatePolicy]').value==='replace',add=parsed.rows.filter(r=>!dupSet.has(r.date)||(replace&&replacements.has(r.date)));guardDates(add.map(r=>r.date));if(!add.length)throw Error('No hay filas nuevas ni reemplazos seleccionados.');if(!confirm('¿Importar '+add.length+' fechas? Se conservará una copia local anterior.'))return;if(mutate(()=>{const ds=new Set(add.map(r=>r.date));state.rows=state.rows.filter(r=>!ds.has(r.date)).concat(add)},'Excel importado.'))closeModal()}catch(e){toast(e.message)}};}
function mappingForm(b64){const wb=XLSX.read(b64,{type:'base64',cellDates:true}),ws=wb.Sheets[wb.SheetNames[0]],raw=XLSX.utils.sheet_to_json(ws,{header:1,defval:null}),header=raw.find(a=>a.some(x=>String(x).toUpperCase()==='FECHA'))||raw[0]||[],options=[['-1','No existe'],...Array.from({length:Math.min(30,Math.max(header.length,10))},(_,i)=>[String(i),XLSX.utils.encode_col(i)+' · '+String(header[i]||'Columna')])];const fields=[['date','Fecha',0],['place','Lugar / actividad',2],['start','Entrada',3],['end','Salida',4],['status','Asistencia',5],['note','Observaciones',6],['breakMinutes','Descanso no pago',7],['overnight','Salida al día siguiente',8],['paid','Día pago',-1]];modal('<h2>Asignar columnas</h2><p class="muted">La asignación se aplica a las hojas de asistencia. Fecha y asistencia son obligatorias.</p><form id="mappingForm">'+fields.map(([k,t,d])=>select(t,k,options,String(d))).join('')+formEnd('Revisar con estas columnas')+'</form>');$('mappingForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),m=Object.fromEntries([...f].map(([k,v])=>[k,Number(v)]));if(m.date<0||m.status<0)return formError('Elegí fecha y asistencia.');importPreview(b64,m)};}
window.receiveFile=(name,b64)=>{try{if(b64.length>14*1024*1024)throw Error('El archivo supera 10 MB.');if(name.toLowerCase().endsWith('.json')){const candidate=Core.migrate(JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(b64),c=>c.charCodeAt(0)))));restorePreview(candidate)}else if(name.toLowerCase().endsWith('.xlsx'))loadLib('xlsx.full.min.js').then(()=>importPreview(b64)).catch(e=>toast(e.message));else throw Error('Elegí un archivo .xlsx o .json')}catch(e){toast('Archivo rechazado: '+e.message)}};
$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10*1024*1024)throw Error('Máximo 10 MB');const b=new Uint8Array(await f.arrayBuffer());let s='';for(let i=0;i<b.length;i+=8192)s+=String.fromCharCode(...b.subarray(i,i+8192));receiveFile(f.name,btoa(s))}catch(e){toast(e.message)}e.target.value=''};
document.querySelectorAll('nav [data-tab]').forEach(b=>{b.querySelector('span').innerHTML=icon(b.dataset.tab);b.onclick=()=>go(b.dataset.tab)});document.querySelector('nav .fab i').innerHTML=icon('plus');document.querySelector('.logo').innerHTML='<svg viewBox="20 22 70 70" aria-hidden="true">'+LOGO.map(([d,f,st,w])=>'<path d="'+d+'" fill="'+(f||'none')+'"'+(st?' stroke="'+st+'" stroke-width="'+w+'" stroke-linecap="round"':'')+'/>').join('')+'</svg>';$('searchBtn').innerHTML=icon('search');$('searchBtn').onclick=openSearch;$('searchClose').innerHTML=icon('left');$('searchClose').onclick=closeSearch;$('searchInput').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(runSearch,120)};$('prev').innerHTML=icon('left');$('next').innerHTML=icon('arrow');$('prev').onclick=()=>shift(-1);$('next').onclick=()=>shift(1);$('periodPick').onclick=()=>{try{$('month').showPicker()}catch(e){$('month').focus();$('month').click()}};document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{$('part').value=b.dataset.part;render()});$('month').value=today().slice(0,7);$('part').value=+today().slice(8)<=15?'1':'2';$('month').onchange=render;$('today').onclick=()=>{$('month').value=today().slice(0,7);$('part').value=+today().slice(8)<=15?'1':'2';render()};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('search').hidden)closeSearch()});window.onhashchange=()=>{const t=location.hash.slice(1);if(['summary','hours','pay','settings','guide'].includes(t)&&t!==tabName){tabName=t;render()}};
let searchTimer;
function openSearch(){$('search').hidden=false;document.body.classList.add('searching');$('searchInput').value='';runSearch();setTimeout(()=>$('searchInput').focus(),60)}
function closeSearch(){$('search').hidden=true;document.body.classList.remove('searching')}
function jumpTo(d){$('month').value=d.slice(0,7);$('part').value=+d.slice(8)<=15?'1':'2'}
function runSearch(){const q=$('searchInput').value,box=$('searchResults');if(!Core.norm(q)){box.innerHTML='<div class="search-hint"><p>Probá con un día, una fecha, un lugar o un importe:</p><div class="chips">'+['lunes','16/11','noviembre','Ausente','transferencia'].map(t=>'<button type="button" class="chip" data-q="'+t+'">'+t+'</button>').join('')+'</div><small>Busca en todas tus jornadas, cobros y ajustes, de cualquier período.</small></div>';box.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{$('searchInput').value=b.dataset.q;runSearch()});return}
 const by=(a,b)=>b.date.localeCompare(a.date),rows=state.rows.filter(r=>(r.status||r.place||r.note)&&Core.matches(Core.searchText('row',r),q)).sort(by),pays=state.payments.filter(p=>Core.matches(Core.searchText('payment',p),q)).sort(by),adj=state.adjustments.filter(a=>Core.matches(Core.searchText('adjustment',a),q)).sort(by),n=rows.length+pays.length+adj.length,long=d=>{const w=new Date(d+'T12:00:00').toLocaleDateString('es-AR',{weekday:'long'});return w[0].toUpperCase()+w.slice(1)+' '+dateLabel(d)};
 box.innerHTML=!n?'<p class="empty">No encontramos nada para “'+esc(q)+'”.</p>':'<p class="search-count">'+n+(n===1?' resultado':' resultados')+(n>60?' · mostrando los más recientes':'')+'</p>'+(rows.length?'<section class="panel"><h3>Jornadas</h3>'+rows.slice(0,60).map(r=>{const c=Core.calc(r,state.rules);return '<button type="button" class="listitem" data-sday="'+r.date+'">'+icon('hours')+'<span><strong>'+esc(long(r.date))+'</strong><small>'+esc(r.place||r.status)+(r.start?' · '+esc(r.start)+'–'+esc(r.end)+' · '+compactHours(c.hours):'')+(r.note?' · '+esc(r.note):'')+'</small></span>'+statusBadge(r)+'</button>'}).join('')+'</section>':'')+(pays.length?'<section class="panel"><h3>Cobros</h3>'+pays.slice(0,60).map(p=>'<button type="button" class="listitem" data-spay="'+esc(p.id)+'">'+icon('pay')+'<span><strong>'+money(p.amount)+'</strong><small>'+dateLabel(p.date)+' · '+esc(p.note||'Cobro')+'</small></span>'+icon('arrow')+'</button>').join('')+'</section>':'')+(adj.length?'<section class="panel"><h3>Ajustes</h3>'+adj.slice(0,60).map(a=>'<button type="button" class="listitem" data-sadj="'+esc(a.id)+'">'+icon('adjust')+'<span><strong>'+money(a.amount)+'</strong><small>'+dateLabel(a.date)+' · '+esc(a.note)+'</small></span>'+icon('arrow')+'</button>').join('')+'</section>':'');
 box.querySelectorAll('[data-sday]').forEach(b=>b.onclick=()=>{const d=b.dataset.sday;closeSearch();jumpTo(d);go('hours');editRow(d)});
 box.querySelectorAll('[data-spay]').forEach(b=>b.onclick=()=>{const p=state.payments.find(x=>x.id===b.dataset.spay);closeSearch();jumpTo(Core.allocatedDate(p));go('pay');paymentForm(p.id)});
 box.querySelectorAll('[data-sadj]').forEach(b=>b.onclick=()=>{const a=state.adjustments.find(x=>x.id===b.dataset.sadj);closeSearch();jumpTo(a.date);go('pay');adjustmentForm(a.id)});}
function guideView(){const secs=[],sec=(id,t,html)=>secs.push([id,t,html]),ex=t=>'<div class="example"><b>Ejemplo</b>'+t+'</div>',f=t=>'<div class="formula">'+t+'</div>';
sec('inicio','Primeros pasos','<ol><li><b>Cargá tu tarifa</b>: Ajustes → Tarifas. Sin tarifa se cuentan horas pero no plata.</li><li><b>Registrá cada día</b> con el botón <b>+</b> de abajo: asistencia, lugar, entrada y salida.</li><li><b>Cargá cada cobro</b> en Pagos cuando te pagan.</li><li>En <b>Quincena</b> ves cuánto generaste, cuánto cobraste y cuánto te deben.</li><li>Activá un <b>recordatorio</b> y exportá una <b>copia</b> cada tanto.</li></ol>');
sec('dias','Registrar un día','<ul><li><b>Asistencia:</b> Presente, Ausente, Franco, Feriado o Licencia. Solo Presente lleva horario. “Sin registrar” no es falta.</li><li><b>Lugar:</b> escribilo o tocá uno de tus lugares frecuentes.</li><li><b>Entrada y salida.</b> Si salís después de medianoche, activá “La salida es al día siguiente”.</li><li><b>Descanso no pago:</b> minutos que se restan.</li><li><b>Pagar aunque no haya trabajado:</b> feriados o licencias pagas (tarifa por día).</li><li><b>Usar última jornada</b> copia lugar y horario del último día trabajado.</li></ul>'+ex('Entrás 22:00, salís 06:00 con 30 min de descanso → activá “salida al día siguiente”, descanso 30 → 7 h 30 min.')+'<p>Para muchos días iguales: Horarios → <b>Cargar varios días</b>.</p>');
sec('doble','Pago doble o especial','<p>En “Pago del día” elegí <b>Normal</b>, <b>×1,5</b>, <b>Doble ×2</b>, <b>Triple ×3</b> u <b>Otro</b> (por ejemplo 1,75). Multiplica la base y las extras <b>solo de ese día</b>; tu tarifa no cambia.</p>'+ex('Tu día vale $50.000. Trabajás un feriado pagado doble: ese día suma $100.000. Si además hiciste 2 h extra a $9.000, suman 2 × $9.000 × 2 = $36.000.')+'<p>Con sueldo mensual, un día ×2 suma un día más de sueldo (sueldo ÷ días del mes).</p>');
sec('tarifas','Tarifas y aumentos','<p>Cada tarifa vale <b>desde su fecha</b> hasta el día anterior a la siguiente. Por eso, cuando te aumentan, <b>no edites la tarifa vieja</b>: tocá <b>Registrar aumento</b>, poné el % o el nuevo importe y desde cuándo. Los días anteriores conservan su valor.</p><ul><li><b>Por día:</b> monto fijo por jornada.</li><li><b>Por hora:</b> horas normales × valor hora.</li><li><b>Mensual:</b> se reparte por días del mes o mitad por quincena.</li><li><b>Hora extra:</b> monto fijo, o <b>recargo %</b> sobre tu valor hora (50 % = la hora extra vale 1,5 horas).</li></ul><p>En el historial cada tarifa muestra su rango de fechas, el % de aumento contra la anterior y cuántos días la usan.</p>'+ex('Cobrabas $50.000/día. Te aumentan 10 % desde el 16/11: Registrar aumento → 10 % → 16/11. Queda $55.000 desde el 16/11 y $50.000 antes.'));
sec('calculo','Cómo se calcula todo','<p>Todas las cuentas se hacen al centavo y con la tarifa vigente en la fecha de cada día.</p>'+f('Horas trabajadas = salida − entrada − descanso<br><small>(+24 h si la salida es al día siguiente)</small>')+f('Horas extra = horas trabajadas − jornada normal<br><small>o, con horario fijo: lo trabajado fuera de ese horario</small>')+f('Valor hora = importe del día ÷ jornada<br><small>por hora: el importe · mensual: sueldo ÷ ('+Core.MONTH_DAYS+' × jornada)</small>')+f('Hora extra = monto fijo<br><small>o valor hora × (1 + recargo %)</small>')+f('Día = (base + horas extra × valor extra) × pago del día')+f('Generado = Σ días + sueldo mensual repartido + ajustes')+f('Pendiente = generado − cobrado')+'<p><b>Pago diario</b> (avanzado): completa siempre, media jornada si trabajás la mitad o menos, o proporcional a las horas normales.</p>'+ex('Día $48.000, jornada 8 h, extra 50 %. Trabajás 08:00 a 18:00 (10 h).<br>Valor hora $6.000 → extra $9.000.<br>$48.000 + 2 × $9.000 = <b>$66.000</b>.'));
sec('periodos','Quincenas y períodos','<ul><li>‹ › cambian de quincena. Tocá el nombre para elegir mes.</li><li><b>1ª</b> = 1 al 15 · <b>2ª</b> = 16 a fin de mes · <b>Mes</b> = completo.</li><li><b>Hoy</b> te devuelve a la quincena actual.</li></ul>');
sec('pagos','Pagos: cobros, ajustes y cierre','<ul><li><b>Registrar cobro:</b> fecha real (cuándo te pagaron) e <b>imputación</b> (qué quincena te pagan).</li><li><b>Cobrar saldo:</b> completa solo el importe pendiente.</li><li><b>Ajuste:</b> viáticos (+) o descuentos y adelantos (−). Motivo obligatorio.</li><li><b>Cerrar:</b> bloquea cambios en días, ajustes y tarifas de esa quincena. No la marca como cobrada.</li></ul>'+ex('El 2/12 te pagan $520.000 por la 2ª de noviembre: fecha real 02/12, imputar a 16/11.')+'<p>Si quedó plata sin cobrar de quincenas anteriores, Quincena muestra un aviso naranja con el total.</p>');
sec('recordatorios','Recordatorios','<p>Ajustes → Recordatorios. Elegí la hora (o una sugerida) y los días, o usá los atajos “Lun a vie”, “Todos”… Arriba ves cuándo llega el próximo aviso.</p><p>Si no llega: revisá que la app tenga permiso de notificaciones y que el ahorro de batería no la restrinja.</p>');
sec('datos','Tus datos y copias','<ul><li>Todo se guarda <b>solo en este teléfono</b>. Ajustes → Tus datos muestra cuántos días, cobros y tarifas tenés, y cuándo exportaste la última copia (te avisa si pasaron más de 14 días).</li><li><b>Copias de seguridad:</b> exportá un .json completo. Además hay versiones automáticas antes de cada cambio; podés revisarlas y restaurarlas.</li><li><b>Google Drive:</b> vinculá un archivo que se actualiza solo.</li><li><b>Importar:</b> Excel con tus horarios (con vista previa) o una copia .json.</li><li><b>Exportar período a Excel</b> y <b>Borrar todos los datos</b> (pide escribir BORRAR y se puede deshacer).</li></ul><div class="warn">Desinstalar la app borra los datos del teléfono. Exportá una copia antes.</div>');
sec('compartir','Compartir tu quincena','<p>En Quincena → <b>Compartir quincena</b>. Elegí qué incluir (pendiente, generado, cobrado, detalle) y el formato: WhatsApp, imagen, PDF, Excel o Word.</p>'+ex('Para reclamar lo que te deben: dejá “Pendiente” y “Detalle”, apagá el resto y elegí WhatsApp.'));
sec('buscar','Buscar','<p>La lupa busca en todas tus jornadas, cobros y ajustes. Sin importar acentos. Podés combinar palabras.</p>'+ex('“lunes depósito” · “16/11” · “ausente” · “doble” · “52000”'));
sec('apariencia','Apariencia','<p>Ajustes → Apariencia: tema Sistema, Claro, Oscuro o AMOLED (negro puro), 8 colores de acento, reducir transparencia y quitar animaciones (más liviano).</p>');
sec('faq','Preguntas frecuentes','<p><b>Cambié la tarifa y cambiaron días viejos.</b><br>Editaste una vigencia existente. Volvé al valor anterior y usá “Registrar aumento”.</p><p><b>Aparece “Sin tarifa”.</b><br>No hay tarifa que empiece antes de ese día. Creá una con fecha anterior.</p><p><b>No puedo editar un día.</b><br>Su quincena está cerrada. Reabrila en Pagos.</p><p><b>El pendiente no baja.</b><br>El cobro está imputado a otra quincena. Editalo y cambiá “Imputar a”.</p><p><b>¿Las extras se pagan doble?</b><br>Solo si ese día tiene pago ×2. Si no, valen su monto fijo o tu recargo %.</p>');
return '<button class="link back" data-go="settings">'+icon('left')+' Ajustes</button><div class="guide-search">'+icon('search')+'<input id="guideQ" type="search" placeholder="Buscar en la guía: doble, aumento, extra…" aria-label="Buscar en la guía"></div><div class="chips toc">'+secs.map(([id,t])=>'<button type="button" class="chip" data-toc="'+id+'">'+t+'</button>').join('')+'</div>'+secs.map(([id,t,h],i)=>'<details class="guide-sec" id="g-'+id+'"'+(i===0?' open':'')+'><summary>'+t+'</summary><div class="guide-body">'+h+'</div></details>').join('')+'<p id="guideNone" class="empty" hidden>No hay temas con esas palabras.</p><p class="footer">Mi Quincena 3.4.0</p>'}
$('dialog').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus()});matchMedia('(prefers-color-scheme: dark)').addEventListener('change',appearance);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&window.Android?.cloudSync)Android.cloudSync()});render();
